import { forwardRef, useCallback, useEffect, useImperativeHandle, useLayoutEffect, useMemo, useRef } from 'react';
import type {
  ChessiroCanvasProps, ChessiroCanvasRef, BoardTheme,
  AnimateMoveOptions, PulseSquareOptions, PieceTiltOptions, PromotionPiece, Square,
  CameraController, CameraDriftOptions, CameraShakeOptions, CameraTiltOptions, CameraZoomOptions,
  CelebrateOptions, CinematicMoveOptions, CinematicPlayback, CinematicStep,
  PlayCinematicOptions, PopBadgeOptions, PopBannerOptions, SquareBurstOptions,
  PromotionBeamOptions, ImplodeOptions, CastleSwapOptions, SpotlightOptions,
  SpotlightHandle, LaserOptions, DrawArrowOptions,
  CheckmateOptions, AnnotationOptions, AnnotationHandle,
} from './types';
import { INITIAL_FEN, readFen } from './utils/fen';
import { screenPos2square } from './utils/coords';
import { useBoardSize } from './hooks/useBoardSize';
import { useInteraction } from './interaction/useInteraction';
import { useKeyboard } from './interaction/useKeyboard';
import { Squares } from './render/Squares';
import { PiecesLayer, type PiecesLayerRef, type DropHint } from './render/Pieces';
import { resolveMoveAnimation } from './core/motion';
import { renderBoardSvg, type BoardSvgOptions, type PieceCode } from './core/boardSvg';
import { loadPieceSetSvgs, svgToImageBlob, type RasterOptions } from './utils/exportImage';
import { prefersReducedMotion } from './cinematics/motion';
import { GhostPiecesLayer } from './render/GhostPieces';
import { SquareLabelsLayer } from './render/SquareLabels';
import { TeachingLayer, type TeachingLayerRef } from './render/TeachingLayer';
import { CinematicLayer, type CinematicLayerRef } from './render/CinematicLayer';
import { createCameraController } from './cinematics/camera';
import { playCinematicScript } from './cinematics/director';
import { ArrowsLayer } from './render/Arrows';
import { Notation } from './render/Notation';
import { PromotionDialog } from './render/Promotion';
import { DragGhost } from './render/DragGhost';
import { Badge } from './render/Badge';
import { OverlaysLayer } from './render/Overlays';

const DEFAULT_THEME: BoardTheme = {
  id: 'Chessiro',
  name: 'Chessiro',
  darkSquare: '#785E45',
  lightSquare: '#DFC29A',
  margin: '#66503B',
  lastMoveHighlight: '#DFAA4E',
  selectedPiece: '#B57340',
};

const EMPTY_ARRAY: any[] = [];
const EMPTY_OBJECT: any = {};

function hasActiveRadius(radius: string | number): boolean {
  if (typeof radius === 'number') return radius > 0;
  const trimmed = radius.trim();
  if (trimmed.length === 0) return false;
  const parsed = Number.parseFloat(trimmed);
  if (Number.isFinite(parsed)) return parsed > 0;
  return true;
}

export const ChessiroCanvas = forwardRef<ChessiroCanvasRef, ChessiroCanvasProps>(
  function ChessiroCanvas(props, ref) {
    const {
      position = INITIAL_FEN,
      orientation = 'white',
      interactive = true,
      turnColor,
      movableColor,
      onMove,
      lastMove,
      dests,
      autoPromoteTo,
      expectedMove,
      onWrongMove,
      wrongMoveFeedback = 'shake',
      premovable,
      arrows = EMPTY_ARRAY,
      onArrowsChange,
      arrowBrushes,
      snapArrowsToValidMoves = true,
      markedSquares,
      onMarkedSquaresChange,
      plyIndex,
      plyArrows,
      onPlyArrowsChange,
      plyMarks,
      onPlyMarksChange,
      theme = DEFAULT_THEME,
      pieceSet,
      flipPieces = false,
      showMargin = true,
      marginThickness = 24,
      marginRadius = 4,
      boardRadius = 0,
      showNotation = true,
      highlightedSquares = EMPTY_OBJECT,
      squareVisuals,
      arrowVisuals,
      notationVisuals,
      promotionVisuals,
      overlayVisuals,
      check,
      moveQualityBadge,
      ghostPieces = EMPTY_ARRAY,
      squareLabels,
      allowDragging = true,
      allowDrawingArrows = true,
      animationDurationMs = 200,
      showAnimations = true,
      moveAnimation,
      blockTouchScroll = false,
      selectedPieceScale,
      dragScale = 1,
      touchDragScale = 1.9,
      dragLiftSquares = 0,
      touchDragLiftSquares = 0.6,
      onPrevious,
      onNext,
      onFirst,
      onLast,
      onFlipBoard,
      onShowThreat,
      onDeselect,
      onSquareClick,
      onClearOverlays,
      overlays = EMPTY_ARRAY,
      overlayRenderer,
      pieces: customPieces,
      className,
      style,
    } = props;

    const boardRef = useRef<HTMLDivElement>(null);
    const piecesLayerRef = useRef<PiecesLayerRef>(null);
    const teachingRef = useRef<TeachingLayerRef>(null);
    const cinematicRef = useRef<CinematicLayerRef>(null);
    const cameraControllerRef = useRef<CameraController | null>(null);
    const playbackRef = useRef<CinematicPlayback | null>(null);
    const { bounds, getFreshBounds } = useBoardSize(boardRef);
    const dropHintRef = useRef<DropHint | null>(null);

    // Presets are strings and option objects are usually inline literals, so
    // key the memo on the fields rather than the object identity.
    const motionOpts = typeof moveAnimation === 'string' ? { preset: moveAnimation } : moveAnimation;
    const motion = useMemo(
      () => resolveMoveAnimation(motionOpts, {
        baseDurationMs: animationDurationMs,
        enabled: showAnimations && (motionOpts?.durationMs !== undefined || animationDurationMs >= 50),
        reducedMotion: prefersReducedMotion(),
      }),
      [
        animationDurationMs, showAnimations,
        motionOpts?.preset, motionOpts?.durationMs, motionOpts?.distanceScaling, motionOpts?.easing,
        motionOpts?.arc, motionOpts?.knightArc, motionOpts?.liftScale, motionOpts?.capture,
        motionOpts?.landing, motionOpts?.appear, motionOpts?.flip, motionOpts?.stagger,
        motionOpts?.snapBack, motionOpts?.respectReducedMotion,
      ],
    );

    const orientationRef = useRef(orientation);
    orientationRef.current = orientation;

    // Lazy: the camera controller (and any camera animation) only exists
    // after the first camera call, so idle boards pay nothing.
    const getCameraController = useCallback((): CameraController => {
      if (!cameraControllerRef.current) {
        cameraControllerRef.current = createCameraController(
          () => boardRef.current,
          () => orientationRef.current === 'white',
        );
      }
      return cameraControllerRef.current;
    }, []);

    const handleImpactShake = useCallback((options: { intensity?: number; durationMs?: number }) => {
      void getCameraController().shake(options);
    }, [getCameraController]);

    useEffect(() => {
      return () => {
        playbackRef.current?.cancel();
        playbackRef.current = null;
      };
    }, []);

    const piecesMap = useMemo(() => readFen(position || INITIAL_FEN), [position]);
    // The imperative layers read this when a method fires, which is always after
    // a commit — so publish it in a layout effect rather than assigning during
    // render. Mutating a ref mid-render is not concurrent-safe: an interrupted
    // or discarded render would leave it describing a position that was never
    // committed. Writing only on change also avoids a per-render allocation.
    // Squares the cinematic layer is covering with a flying clone. Shared by
    // reference so the suppression is already in place when the caller's
    // position commit renders the piece.
    const suppressedSquaresRef = useRef<Set<string>>(new Set());
    const boardStateRef = useRef({ pieces: piecesMap, asWhite: orientation === 'white' });
    useLayoutEffect(() => {
      boardStateRef.current = { pieces: piecesMap, asWhite: orientation === 'white' };
    }, [piecesMap, orientation]);

    const boundsToDomRect = useCallback((b: { left: number; top: number; width: number; height: number }): DOMRect => {
      return {
        left: b.left, top: b.top,
        width: b.width, height: b.height,
        right: b.left + b.width,
        bottom: b.top + b.height,
        x: b.left, y: b.top,
        toJSON: () => ({}),
      } as DOMRect;
    }, []);

    const getFreshDomRect = useCallback((): DOMRect | null => {
      const fresh = getFreshBounds();
      return fresh ? boundsToDomRect(fresh) : null;
    }, [getFreshBounds, boundsToDomRect]);

    // Guided mode: only the expected move(s) pass through to onMove; anything
    // else is rejected (piece snaps back), shakes and fires onWrongMove.
    const guardedOnMove = useCallback(
      (from: string, to: string, promotion?: PromotionPiece): boolean => {
        if (expectedMove) {
          const accepted = (Array.isArray(expectedMove) ? expectedMove : [expectedMove]).some(
            (m) =>
              m.from === from &&
              m.to === to &&
              (m.promotion === undefined || m.promotion === promotion),
          );
          if (!accepted) {
            if (wrongMoveFeedback === 'shake') {
              teachingRef.current?.shakePiece(from);
            }
            onWrongMove?.(from, to);
            return false;
          }
        }
        return onMove?.(from, to, promotion) ?? false;
      },
      [expectedMove, onMove, onWrongMove, wrongMoveFeedback],
    );

    // The drag ghost floats `liftSquares` above the pointer; snap back from
    // where the piece was drawn, not from under the finger.
    const liftRef = useRef({ touch: touchDragLiftSquares, mouse: dragLiftSquares });
    liftRef.current = { touch: touchDragLiftSquares, mouse: dragLiftSquares };
    const handleDropRejected = useCallback((square: string, clientX: number, clientY: number, isTouch: boolean) => {
      const rect = getFreshBounds();
      const lift = (isTouch ? liftRef.current.touch : liftRef.current.mouse) * ((rect?.width ?? 0) / 8);
      piecesLayerRef.current?.snapBack(square, clientX, clientY - lift);
    }, [getFreshBounds]);

    const interaction = useInteraction({
      position,
      pieces: piecesMap,
      orientation,
      interactive,
      allowDragging,
      allowDrawingArrows,
      boardRef,
      boardBounds: null,
      onMove: onMove ? guardedOnMove : undefined,
      dests,
      autoPromoteTo,
      turnColor,
      movableColor,
      premovable,
      arrows,
      onArrowsChange,
      arrowBrushes,
      snapArrowsToValidMoves,
      markedSquares,
      onMarkedSquaresChange,
      plyIndex,
      plyArrows,
      onPlyArrowsChange,
      plyMarks,
      onPlyMarksChange,
      onSquareClick,
      onClearOverlays,
      blockTouchScroll,
      getFreshBounds: getFreshDomRect,
      dropHintRef,
      onDropRejected: handleDropRejected,
    });

    const occupiedSquares = useMemo(() => {
      if (interaction.legalSquares.length === 0 && interaction.premoveSquares.length === 0) {
        return undefined;
      }
      const set = new Set<string>();
      for (const sq of piecesMap.keys()) set.add(sq);
      return set;
    }, [piecesMap, interaction.legalSquares, interaction.premoveSquares]);

    const getPieceElement = useCallback((square: string): HTMLDivElement | null => {
      return piecesLayerRef.current?.getPieceElement(square) ?? null;
    }, []);

    const handleDeselect = useCallback(() => {
      interaction.clearSelection();
      onDeselect?.();
    }, [interaction.clearSelection, onDeselect]);

    useKeyboard({
      onPrevious,
      onNext,
      onFirst,
      onLast,
      onFlipBoard,
      onShowThreat,
      onDeselect: handleDeselect,
    });

    // Everything a snapshot needs, published after each commit so the
    // imperative export never reads a render that didn't land.
    const snapshotRef = useRef<() => BoardSvgOptions>(() => ({}));
    useLayoutEffect(() => {
      snapshotRef.current = () => {
        const rect = getFreshBounds();
        const squarePx = rect && rect.width > 0 ? rect.width / 8 : 64;
        const pieceUrls: Partial<Record<PieceCode, string>> | undefined = pieceSet?.path
          ? Object.fromEntries(
            (['wp', 'wn', 'wb', 'wr', 'wq', 'wk', 'bp', 'bn', 'bb', 'br', 'bq', 'bk'] as PieceCode[])
              .map((c) => [c, `${pieceSet.path}/${c}.svg`]),
          )
          : undefined;
        return {
          position,
          orientation,
          theme,
          showMargin,
          marginSquares: marginThickness / squarePx,
          marginRadius: typeof marginRadius === 'number' ? marginRadius : Number.parseFloat(marginRadius) || 0,
          showCoordinates: showNotation,
          lastMove: lastMove ?? null,
          check: check ?? null,
          highlightedSquares,
          markedSquares: Object.keys(interaction.activeMarkedSquares),
          arrows: interaction.renderedArrows,
          arrowBrushes,
          flipPieces,
          pieceUrls,
          size: Math.round(rect && rect.width > 0 ? rect.width + 2 * (showMargin ? marginThickness : 0) : 512),
        };
      };
    });

    useImperativeHandle(ref, () => ({
      getSquareRect(square: string) {
        const fresh = getFreshBounds();
        if (!fresh) return null;
        const file = square.charCodeAt(0) - 97;
        const rank = parseInt(square[1]) - 1;
        const asWhite = orientation === 'white';
        const col = asWhite ? file : 7 - file;
        const row = asWhite ? 7 - rank : rank;
        const sqW = fresh.width / 8;
        const sqH = fresh.height / 8;
        return new DOMRect(fresh.left + col * sqW, fresh.top + row * sqH, sqW, sqH);
      },
      getBoardRect() {
        return getFreshDomRect();
      },
      getSquareAtPoint(clientX: number, clientY: number): Square | null {
        const fresh = getFreshDomRect();
        if (!fresh) return null;
        return screenPos2square(clientX, clientY, orientation === 'white', fresh) ?? null;
      },
      animateMove(from: string, to: string, options?: AnimateMoveOptions) {
        return teachingRef.current?.animateMove(from, to, options) ?? Promise.resolve();
      },
      pulseSquare(square: string, options?: PulseSquareOptions) {
        return teachingRef.current?.pulseSquare(square, options) ?? Promise.resolve();
      },
      shakePiece(square: string) {
        return teachingRef.current?.shakePiece(square) ?? Promise.resolve();
      },
      tiltPiece(square: string, options?: PieceTiltOptions) {
        return teachingRef.current?.tiltPiece(square, options) ?? Promise.resolve();
      },
      resetPieceTilt(square?: string, durationMs?: number) {
        return teachingRef.current?.resetPieceTilt(square, durationMs) ?? Promise.resolve();
      },
      clearTeachingEffects() {
        teachingRef.current?.clearEffects();
      },
      cinematicMove(from: Square, to: Square, options?: CinematicMoveOptions) {
        return cinematicRef.current?.cinematicMove(from, to, options) ?? Promise.resolve();
      },
      squareBurst(square: Square, options?: SquareBurstOptions) {
        return cinematicRef.current?.squareBurst(square, options) ?? Promise.resolve();
      },
      popBadge(square: Square, options: PopBadgeOptions) {
        return cinematicRef.current?.popBadge(square, options) ?? Promise.resolve();
      },
      celebrate(options?: CelebrateOptions) {
        return cinematicRef.current?.celebrate(options) ?? Promise.resolve();
      },
      popBanner(options: PopBannerOptions) {
        return cinematicRef.current?.popBanner(options) ?? Promise.resolve();
      },
      promotionBeam(square: Square, options?: PromotionBeamOptions) {
        return cinematicRef.current?.promotionBeam(square, options) ?? Promise.resolve();
      },
      implode(square: Square, options?: ImplodeOptions) {
        return cinematicRef.current?.implode(square, options) ?? Promise.resolve();
      },
      checkmate(square: Square, options?: CheckmateOptions) {
        return cinematicRef.current?.checkmate(square, options) ?? Promise.resolve();
      },
      annotate(square: Square, text: string, options?: AnnotationOptions): AnnotationHandle {
        return (
          cinematicRef.current?.annotate(square, text, options)
          ?? { setText: () => {}, clear: () => Promise.resolve() }
        );
      },
      castleSwap(kingFrom: Square, kingTo: Square, rookFrom: Square, rookTo: Square, options?: CastleSwapOptions) {
        return cinematicRef.current?.castleSwap(kingFrom, kingTo, rookFrom, rookTo, options) ?? Promise.resolve();
      },
      spotlight(squares: Square[], options?: SpotlightOptions): SpotlightHandle {
        return cinematicRef.current?.spotlight(squares, options) ?? { clear: () => Promise.resolve() };
      },
      drawLaser(from: Square, to: Square, options?: LaserOptions) {
        return cinematicRef.current?.drawLaser(from, to, options) ?? Promise.resolve();
      },
      drawArrow(from: Square, to: Square, options?: DrawArrowOptions) {
        return cinematicRef.current?.drawArrow(from, to, options) ?? Promise.resolve();
      },
      clearCinematics() {
        playbackRef.current?.cancel();
        playbackRef.current = null;
        cinematicRef.current?.clearCinematics();
        cameraControllerRef.current?.reset();
      },
      playCinematic(steps: CinematicStep[], options?: PlayCinematicOptions) {
        playbackRef.current?.cancel();
        const playback = playCinematicScript(
          {
            getLayer: () => cinematicRef.current,
            getCamera: getCameraController,
            peekCamera: () => cameraControllerRef.current,
          },
          steps,
          options,
        );
        playbackRef.current = playback;
        return playback;
      },
      toSVG(options?: BoardSvgOptions) {
        return renderBoardSvg({ ...snapshotRef.current(), ...options });
      },
      async toImage(options?: BoardSvgOptions & RasterOptions) {
        const base = snapshotRef.current();
        let pieceSvgs = options?.pieceSvgs;
        if (!pieceSvgs && base.pieceUrls) {
          const path = pieceSet?.path;
          if (path) pieceSvgs = await loadPieceSetSvgs(path);
        }
        const svg = renderBoardSvg({ ...base, ...options, pieceSvgs, pieceUrls: undefined });
        return svgToImageBlob(svg, options);
      },
      camera: {
        zoomTo: (square: Square, options?: CameraZoomOptions) => getCameraController().zoomTo(square, options),
        zoomOut: (options?: CameraZoomOptions) => getCameraController().zoomOut(options),
        tilt: (options?: CameraTiltOptions) => getCameraController().tilt(options),
        shake: (options?: CameraShakeOptions) => getCameraController().shake(options),
        drift: (options?: CameraDriftOptions) => getCameraController().drift(options),
        reset: () => cameraControllerRef.current?.reset(),
      },
    }), [orientation, getFreshBounds, getFreshDomRect, getCameraController, pieceSet?.path]);

    const hasValidSize = bounds && bounds.width > 0;
    const boardWidth = bounds?.width ?? 0;
    const boardHeight = bounds?.height ?? 0;
    const squareSize = boardWidth / 8;

    // Cursor: grab when hovering pieces, grabbing while dragging
    const isDragging = !!interaction.drag;
    const cursor = !interactive ? 'default' : isDragging ? 'grabbing' : allowDragging ? 'grab' : 'pointer';

    const marginPx = showMargin ? marginThickness : 0;
    const clipBoardContent = hasActiveRadius(boardRadius);

    return (
      <div
        className={className}
        style={{
          position: 'relative',
          ...style,
        }}
        tabIndex={-1}
      >
        {/* Margin frame */}
        {marginPx > 0 && (
          <div
            style={{
              position: 'absolute',
              inset: 0,
              background: theme.margin || theme.darkSquare,
              borderRadius: marginRadius,
              pointerEvents: 'none',
            }}
          />
        )}
        <div
          style={{
            position: 'relative',
            padding: marginPx,
          }}
        >
          <div
            ref={boardRef}
            style={{
              position: 'relative',
              width: '100%',
              paddingBottom: '100%',
              borderRadius: boardRadius,
              overflow: 'visible',
              cursor,
              userSelect: 'none',
              WebkitUserSelect: 'none',
              touchAction: blockTouchScroll ? 'none' : undefined,
            }}
            onMouseDown={interaction.handlePointerDown as any}
            onTouchStart={interaction.handlePointerDown as any}
          >
            <div
              style={{
                position: 'absolute',
                inset: 0,
                borderRadius: boardRadius,
                overflow: clipBoardContent ? 'hidden' : 'visible',
              }}
            >
              <Squares
                theme={theme}
                orientation={orientation}
                lastMove={lastMove}
                selectedSquare={interaction.selectedSquare}
                draggingSquare={interaction.drag?.origSquare}
                dragHoverSquare={interaction.dragHoverSquare}
                legalSquares={interaction.legalSquares}
                premoveSquares={interaction.premoveSquares}
                premoveCurrent={interaction.premoveCurrent}
                occupiedSquares={occupiedSquares}
                markedSquares={interaction.activeMarkedSquares}
                highlightedSquares={highlightedSquares}
                squareVisuals={squareVisuals}
                check={check}
              />

              {ghostPieces.length > 0 && (
                <GhostPiecesLayer
                  ghosts={ghostPieces}
                  orientation={orientation}
                  pieceSet={pieceSet}
                  customPieces={customPieces}
                  flipPieces={flipPieces}
                />
              )}

              <PiecesLayer
                ref={piecesLayerRef}
                pieces={piecesMap}
                orientation={orientation}
                pieceSet={pieceSet}
                customPieces={customPieces}
                flipPieces={flipPieces}
                motion={motion}
                dropHintRef={dropHintRef}
                draggingSquare={interaction.drag?.origSquare}
                selectedSquare={interaction.selectedSquare}
                suppressedSquaresRef={suppressedSquaresRef}
                selectedPieceScale={selectedPieceScale}
              />

              {squareLabels && (
                <SquareLabelsLayer labels={squareLabels} orientation={orientation} />
              )}

              <TeachingLayer
                ref={teachingRef}
                boardStateRef={boardStateRef}
                pieceSet={pieceSet}
                customPieces={customPieces}
                flipPieces={flipPieces}
                getPieceElement={getPieceElement}
              />

              <CinematicLayer
                ref={cinematicRef}
                boardStateRef={boardStateRef}
                suppressedSquaresRef={suppressedSquaresRef}
                pieceSet={pieceSet}
                customPieces={customPieces}
                flipPieces={flipPieces}
                getPieceElement={getPieceElement}
                onImpactShake={handleImpactShake}
              />

              {hasValidSize && (
                <>
                  <ArrowsLayer
                    arrows={interaction.renderedArrows}
                    orientation={orientation}
                    boardWidth={boardWidth}
                    boardHeight={boardHeight}
                    visuals={arrowVisuals}
                  />

                  {moveQualityBadge && (
                    <Badge
                      badge={moveQualityBadge}
                      orientation={orientation}
                      squareSize={squareSize}
                    />
                  )}

                  {overlays.length > 0 && (
                    <OverlaysLayer
                      overlays={overlays}
                      orientation={orientation}
                      boardWidth={boardWidth}
                      boardHeight={boardHeight}
                      renderer={overlayRenderer}
                      visuals={overlayVisuals}
                    />
                  )}

                  {interaction.pendingPromotion && (
                    <PromotionDialog
                      promotion={interaction.pendingPromotion}
                      pieceSet={pieceSet}
                      flipPieces={flipPieces}
                      visuals={promotionVisuals}
                      orientation={orientation}
                      boardWidth={boardWidth}
                      boardHeight={boardHeight}
                      onSelect={interaction.handlePromotionSelect}
                      onDismiss={interaction.handlePromotionDismiss}
                    />
                  )}
                </>
              )}
            </div>

            {showNotation && (
              <Notation
                orientation={orientation}
                theme={theme}
                showOnMargin={showMargin}
                marginThickness={marginThickness}
                marginRadius={marginRadius}
                visuals={notationVisuals}
              />
            )}
          </div>
        </div>

        {interaction.drag && (
          <DragGhost
            ref={interaction.dragGhostRef}
            piece={interaction.drag.piece}
            x={interaction.drag.startPos[0]}
            y={interaction.drag.startPos[1]}
            squareSize={squareSize}
            pieceSet={pieceSet}
            customPieces={customPieces}
            flipPieces={flipPieces}
            scale={interaction.drag.isTouch ? touchDragScale : dragScale}
            liftSquares={interaction.drag.isTouch ? touchDragLiftSquares : dragLiftSquares}
          />
        )}
      </div>
    );
  },
);
